public static String convertDatesToWeekdays(String date) {
        // Split the date string into month, day, and year
        String[] dateParts = date.split("\\s+");
        int month = Integer.parseInt(dateParts[0]);
        int day = Integer.parseInt(dateParts[1]);
        int year = Integer.parseInt(dateParts[2]);

        // Create a Calendar object with the given date
        Calendar calendar = Calendar.getInstance();
        calendar.set(Calendar.MONTH, month - 1);
        calendar.set(Calendar.DAY_OF_MONTH, day);
        calendar.set(Calendar.YEAR, year);

        // Get the weekday for the given date
        int weekday = calendar.get(Calendar.DAY_OF_WEEK);

        // Convert the weekday to a string
        String weekdayString;
        switch (weekday) {
            case Calendar.SUNDAY:
                weekdayString = "Sunday";
                break;
            case Calendar.MONDAY:
                weekdayString = "Monday";
                break;
            case Calendar.TUESDAY:
                weekdayString = "Tuesday";
                break;
            case Calendar.WEDNESDAY:
                weekdayString = "Wednesday";
                break;
            case Calendar.THURSDAY:
                weekdayString = "Thursday";
                break;
            case Calendar.FRIDAY:
                weekdayString = "Friday";
                break;
            case Calendar.SATURDAY:
                weekdayString = "Saturday";
                break;
            default:
                throw new IllegalArgumentException("Invalid weekday: " + weekday);
        }

        // Return the result
        return String.format("%s %s, %s is a %s", month, day, year, weekdayString);
    }

public static String convertDatesToWeekdays(String date) {
