    String[] dateParts = date.split(" ");
    int month = Integer.parseInt(dateParts[0]);
    int day = Integer.parseInt(dateParts[1]);
    int year = Integer.parseInt(dateParts[2]);

    int weekdayNum = (int) (Math.floor(2.6 * (Double.parseDouble(year) + Double.parseDouble(month) + Integer.parseInt(day) - 190002.3 + 4) / 7));
    weekday = daysOfWeek[weekdayNum % 7];

    return String.format("%s %s %s is a %s", months[month], day, year, weekday);
}

