public double trimMean(int[] arr) {
    Arrays.sort(arr);
    int n = arr.length;
    int nTrim = (int) Math.ceil(0.05 * n);
    int firstIndex = nTrim;
    int lastIndex = n - nTrim - 1;
    double sum = 0;
    for (int i = firstIndex; i <= lastIndex; i++) {
        sum += arr[i];
    }
    return sum / (lastIndex - firstIndex + 1);
}

public double trimMean(int[] arr) {
    int n = arr.length;
    int k = (int) Math.ceil(n * 0.05); // Smallest 5% and largest 5% of elements
    Arrays.sort(arr);
    int sum = 0;
    for (int i = k; i < n - k; i++) {
        sum += arr[i];
    }
    return (double) sum / (n - 2 * k);
}

public double trimMean(int[] arr) {
    Arrays.sort(arr);
    int n = arr.length;
    int minIdx = (int) Math.ceil(0.05 * n);
    int maxIdx = (int) Math.floor(0.95 * n);
    double sum = 0;
    for (int i = minIdx; i <= maxIdx; i++) {
        sum += arr[i];
    }
    return sum / (maxIdx - minIdx + 1);
}

public double trimMean(int[] arr) {
    Arrays.sort(arr);
    int numElementsToRemove = (int) Math.ceil(arr.length * 0.05);
    int startIndex = numElementsToRemove;
    int endIndex = arr.length - numElementsToRemove;
    double sum = 0;
    for (int i = startIndex; i < endIndex; i++) {
        sum += arr[i];
    }
    return sum / (arr.length - 2 * numElementsToRemove);
}

public double trimMean(int[] arr) {
    // Calculate the number of elements to remove from the smallest and largest 5% of the array
    int removeSmallest = (int) Math.ceil(arr.length * 0.05);
    int removeLargest = (int) Math.ceil(arr.length * 0.05);

    // Use quickselect to find the kth smallest element
    int kthSmallest = kthSmallest(arr, removeSmallest + 1);
    int kthLargest = kthLargest(arr, arr.length - removeLargest);

    // Remove the smallest and largest elements
    List<Integer> filteredArr = Arrays.stream(arr).boxed().filter(x -> x != kthSmallest && x != kthLargest).collect(Collectors.toList());

    // Calculate the mean of the remaining elements
    double mean = filteredArr.stream().mapToInt(x -> x).average().getAsDouble();

    return mean;
}

public boolean canArrange(int[] arr, int k) {
    int n = arr.length / 2;
    int[] counts = new int[k];
    for (int i = 0; i < arr.length; i++) {
        int idx = arr[i] % k;
        counts[idx]++;
    }
    for (int i = 0; i < k; i++) {
        if (counts[i] % 2 == 1) {
            return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    Arrays.sort(arr);
    int n = arr.length / 2;
    for (int i = 0; i < n; i++) {
        if (arr[i] % k != 0 || arr[arr.length - 1 - i] % k != 0) {
            return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    int[] freq = new int[k];
    for (int i = 0; i < n; i++) {
        freq[(arr[i] % k + k) % k]++;
    }
    for (int i = 1; i < k; i++) {
        if (freq[i] % 2 == 1) {
            return false;
        }
    }
    return true;
}

public static boolean canArrange(int[] arr, int k) {
    // Initialize a hash map to store the counts of each remainder
    Map<Integer, Integer> counts = new HashMap();

    // Iterate through the array and calculate the remainder of each element divided by k
    for (int num : arr) {
        int remainder = num % k;

        // If the remainder is already in the hash map, increment the count by 1
        if (counts.containsKey(remainder)) {
            counts.put(remainder, counts.get(remainder) + 1);
        }
        // Else, add the remainder to the hash map with a count of 1
        else {
            counts.put(remainder, 1);
        }
    }

    // Check if the sum of the counts for each remainder is divisible by 2
    int countSum = counts.values().stream().mapToInt(Integer::intValue).sum();
    return countSum % 2 == 0;
}

public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    if (n % 2 == 1) return false;
    int[] prefixSums = new int[n + 1];
    for (int i = 1; i <= n; i++) {
        prefixSums[i] = prefixSums[i - 1] + arr[i - 1];
    }
    int sum = prefixSums[n];
    for (int i = 1; i <= n / 2; i++) {
        if (prefixSums[i] % k == 0 && (sum - prefixSums[i]) % k == 0) {
            return true;
        }
    }
    return false;
}

