    int[] dist = new int[n];
    Arrays.fill(dist, Integer.MAX_VALUE);
    dist[0] = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < edges.length; j++) {
            int u = edges[j][0];
            int v = edges[j][1];
            if (dist[u] != Integer.MAX_VALUE && dist[u] + 1 < dist[v]) {
                dist[v] = dist[u] + 1;
            }
        }
    }
    int totalTime = 0;
    for (int i = 0; i < n; i++) {
        if (hasApple[i]) {
            totalTime += dist[i];
        }
    }
    return totalTime;
}

