        charSet.add(s.charAt(i));
    }
    while (charSet.size() > 0) {
        char minChar = getMinChar(s, charSet);
        charSet.remove(minChar);
        result += minChar;
        char maxChar = getMaxChar(s, charSet);
        charSet.remove(maxChar);
        result += maxChar;
