public String sortString(String s) {
    StringBuilder sb = new StringBuilder();
    while (s.length() > 0) {
        char smallest = s.charAt(0);
        int smallestIndex = 0;
        char largest = s.charAt(0);
        int largestIndex = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) < smallest) {
                smallest = s.charAt(i);
                smallestIndex = i;
            } else if (s.charAt(i) > largest) {
                largest = s.charAt(i);
                largestIndex = i;
            }
        }
        sb.append(smallest);
        s = s.substring(0, smallestIndex) + s.substring(smallestIndex + 1);
        sb.append(largest);
        s = s.substring(0, largestIndex) + s.substring(largestIndex + 1);
    }
    return sb.toString();
}

public String sortString(String s) {
    char[] chars = s.toCharArray();
    Arrays.sort(chars);
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < chars.length; i++) {
        result.append(chars[i]);
        if (i % 2 == 1 && i != chars.length - 1) {
            char current = chars[i];
            for (int j = i + 1; j < chars.length; j++) {
                if (current > chars[j]) {
                    result.append(chars[j]);
                    current = chars[j];
                    break;
                }
            }
        }
    }
    return result.toString();
}

public String sortString(String s) {
    int n = s.length();
    char[] result = new char[n];
    char[] arr = s.toCharArray();

    // Step 1: pick the smallest character from s and append it to the result
    Arrays.sort(arr);
    result[0] = arr[0];

    // Step 2: pick the smallest character from s which is greater than the last appended character to the result and append it
    for (int i = 1; i < n; i++) {
        int currChar = (int) result[i - 1];
        int index = Arrays.binarySearch(arr, currChar + 1);
        if (index >= 0) {
            result[i] = arr[index];
        } else {
            int temp = arr[index * -1 - 1];
            result[i] = temp;
        }
    }

    // Step 3: pick the largest character from s and append it to the result
    for (int i = n - 1; i >= 0; i--) {
        if (i != n - 1) {
            int currChar = (int) result[i + 1];
            int index = Arrays.binarySearch(arr, currChar);
            if (index >= 0) {
                result[i] = arr[index];
            } else {
                int temp = arr[index * -1 - 1];
                result[i] = temp;
            }
        } else {
            int currChar = (int) result[i - 1];
            int index = Arrays.binarySearch(arr, currChar);
            if (index >= 0) {
                result[i] = arr[index];
            } else {
                int temp = arr[index * -1 - 1];
                result[i] = temp;
            }
        }
    }

    // Step 4: pick the largest character from s which is smaller than the last appended character to the result and append it
    for (int i = n - 1; i >= 0; i--) {
        int currChar = (int) result[i];
        int index = Arrays.binarySearch(arr, currChar);
        if (index >= 0) {
            result[i] = arr[index];
        } else {
            int temp = arr[index * -1 - 1];
            result[i] = temp;
        }
    }

    return new String(result);
}

public String sortString(String s) {
    char[] chars = s.toCharArray();
    Arrays.sort(chars);
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < chars.length; i++) {
        if (Character.isLowerCase(chars[i])) {
            result.append(chars[i]);
        }
    }
    for (int i = chars.length - 1; i >= 0; i--) {
        if (Character.isUpperCase(chars[i])) {
            result.append(chars[i]);
        }
    }
    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    int average = sum / nums.length;
    int sum1 = 0, sum2 = 0;
    int length1 = 0, length2 = 0;
    for (int i = 0; i < nums.length; i++) {
        if (length1 < length2 || (length1 == length2 && sum1 <= sum2)) {
            sum1 += nums[i];
            length1++;
        } else {
            sum2 += nums[i];
            length2++;
        }
        if (length1 != 0 && length2 != 0 && sum1 != sum2) {
            return false;
        }
    }
    return true;
}

public boolean splitArraySameAverage(int[] nums) {
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    int n = nums.length;
    if (n == 1) {
        return true;
    }
    if (sum % n != 0) {
        return false;
    }
    int avg = sum / n;
    int[] prefixSums = new int[n];
    for (int i = 0; i < n; i++) {
        prefixSums[i] = nums[i];
    }
    for (int i = 1; i < n; i++) {
        prefixSums[i] += prefixSums[i - 1];
    }
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (prefixSums[j] - prefixSums[i] == avg * (j - i)) {
                return true;
            }
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    int avg = sum / nums.length;
    int leftSum = 0;
    for (int i = 0; i < nums.length / 2; i++) {
        leftSum += nums[i];
    }
    if (leftSum == avg * 2) {
        return true;
    }
    int rightSum = 0;
    for (int i = nums.length / 2; i < nums.length; i++) {
        rightSum += nums[i];
    }
    return rightSum == avg * 2;
}

public boolean splitArraySameAverage(int[] nums) {
    double sum = 0;
    for (int num : nums) {
        sum += num;
    }
    double avg = sum / nums.length;
    sum = 0;
    for (int i = 0; i < nums.length / 2; i++) {
        sum += nums[i];
    }
    if (sum / (nums.length / 2) != avg) {
        return false;
    }
    sum = 0;
    for (int i = nums.length / 2; i < nums.length; i++) {
        sum += nums[i];
    }
    return sum / (nums.length / 2) == avg;
}

public boolean splitArraySameAverage(int[] nums) {
    double sum = 0;
    for (int num : nums) {
        sum += num;
    }
    double avg = sum / nums.length;
    double sum1 = 0;
    double sum2 = 0;
    int i = 0;
    while (i < nums.length - 1) {
        sum1 += nums[i];
        sum2 += nums[i + 1];
        if (sum1 / (i + 1) == avg && sum2 / (nums.length - i - 1) == avg) {
            return true;
        }
        i++;
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int firstStep = 0, secondStep = 0;
    for (int i = 0; i < cost.length; i++) {
        int currentStep = Math.min(firstStep, secondStep) + cost[i];
        firstStep = secondStep;
        secondStep = currentStep;
    }
    return Math.min(firstStep, secondStep);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < n; i++) {
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i];
    }
    return Math.min(dp[n - 1], dp[n - 2]);
}

