public int minCostClimbingStairs(int[] cost) {
    int prevMinCost = 0;
    int currMinCost = 0;
    for (int i = 2; i < cost.length; i++) {
        int tmp = currMinCost;
        currMinCost = Math.min(currMinCost, prevMinCost) + cost[i];
        prevMinCost = tmp;
    }
    return Math.min(currMinCost, prevMinCost);
}

