public int minInsertions(String s) {
    int leftCount = 0;
    int rightCount = 0;

    for (char c : s.toCharArray()) {
        if (c == '(') {
            leftCount++;
        } else {
            rightCount++;
        }
    }

    int diff = leftCount - rightCount;
    if (diff < 0) {
        return -1;
    } else if (diff > 1) {
        return -1;
    }

    int insertions = 0;
    if (diff == 0) {
        return insertions;
    } else if (diff == 1) {
        insertions++;
    }

    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '(' && i == 0) {
            insertions++;
        } else if (s.charAt(i) == '(') {
            insertions++;
        } else if (s.charAt(i) == ')' && s.charAt(i - 1) == '(') {
            insertions++;
        }
    }

    return insertions;
}

public int minInsertions(String s) {
