    // Iterate through the string and check for unbalanced parentheses
    for (char c : s.toCharArray()) {
      if (c == '(') left++;
      else right++;
      if (left < right) min++;
      else if (left > right) min += 2;
    }

    // Return the minimum number of insertions required to balance the parentheses
    return min;
