    fib[1] = 1;
    for (int i = 2; i <= k; i++) {
        fib[i] = fib[i - 1] + fib[i - 2];
    }
    int min = Integer.MAX_VALUE;
    for (int i = 1; i <= k; i++) {
        if (fib[i] == k) {
            return i;
        } else if (fib[i] < min && k - fib[i] >= 0 && fib[i] + fib[k - fib[i]] == k) {
