public String getSmallestString(int n, int k) {
    // Use a combination of alphabetic and numeric characters
    // to generate the smallest possible string
    String s = "";
    int alphabetSize = 26;
    int numDigits = 10;
    int i = 1;
    while (i <= n) {
        if (k >= i && k <= alphabetSize + i) {
            // The i-th character is alphabetical
            s += (char)('a' + k - i);
            i++;
        } else if (k >= alphabetSize + i && k <= alphabetSize + i + numDigits) {
            // The i-th character is numeric
            int digitValue = k - (alphabetSize + i);
            s += (char)('0' + digitValue);
            i++;
        } else {
            // The i-th character is a special character
            s += (char)('!' + i);
            i++;
        }
        k -= i;
    }
    return s;
}

