public String getSmallestString(int n, int k) {
    if (n == 0) {
        return "";
    }
    int alphabetSize = 26;
    int[] frequency = new int[alphabetSize];
    for (int i = 0; i < n; i++) {
        frequency[k % alphabetSize - 1]++;
        k /= alphabetSize;
    }

    if (k != 0) {
        return "";
    }

    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < frequency.length; i++) {
        for (int j = 0; j < frequency[i]; j++) {
            sb.append((char) (i + 'a'));
        }
    }

    return sb.toString();
}

