public static int longestLine(int[][] mat) {
    int m = mat.length;
    int n = mat[0].length;
    int maxLen = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                int currentLen = 1;
                // horizontal
                for (int k = j + 1; k < n && mat[i][k] == 1; k++) {
                    currentLen++;
                }
                // vertical
                for (int k = i + 1; k < m && mat[k][j] == 1; k++) {
                    currentLen++;
                }
                // diagonal
                for (int k = 1; i + k < m && j + k < n && mat[i + k][j + k] == 1; k++) {
                    currentLen++;
                }
                // anti-diagonal
                for (int k = 1; i + k < m && j - k >= 0 && mat[i + k][j - k] == 1; k++) {
                    currentLen++;
                }
                maxLen = Math.max(maxLen, currentLen);
            }
        }
    }

    return maxLen;
}

public static int longestLine(int[][] mat) {
    int maxLength = 0;
    for (int i = 0; i < mat.length; i++) {
        for (int j = 0; j < mat[0].length; j++) {
            int currentLength = 0;
            if (mat[i][j] == 1) {
                currentLength = 1;
                int[][] directions = {
                    {0, 1},
                    {1, 0},
                    {1, 1},
                    {1, -1}
                };
                for (int[] direction : directions) {
                    int x = i + direction[0];
                    int y = j + direction[1];
                    while (x >= 0 && x < mat.length && y >= 0 && y < mat[0].length && mat[x][y] == 1) {
                        currentLength++;
                        x += direction[0];
                        y += direction[1];
                    }
                }
            }
            maxLength = Math.max(maxLength, currentLength);
        }
    }
    return maxLength;
}

