    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                dp[i][j] = 1;
                for (int k = i - 1; k >= 0; k--) {
                    if (dp[k][j] > 0) {
                        dp[i][j] = Math.max(dp[i][j], dp[k][j] + 1);
                    }
                }
                for (int k = j - 1; k >= 0; k--) {
                    if (dp[i][k] > 0) {
                        dp[i][j] = Math.max(dp[i][j], dp[i][k] + 1);
                    }
                }
                maxLen = Math.max(maxLen, dp[i][j]);
            }
        }
    }

    return maxLen;
}

