public static String addThousandSeparator(int n) {
    String result = "";
    String strN = Integer.toString(n);
    int thousands = strN.length() / 3;
    int digits = strN.length() % 3;
    if (thousands <= 0) {
        result = strN;
    } else if (digits == 0) {
        result = strN.substring(0, thousands * 3);
        result += ".";
        result += strN.substring(thousands * 3);
    } else {
        result = strN.substring(0, thousands * 3 + digits);
        result += ".";
        result += strN.substring(thousands * 3 + digits);
    }
    return result;
}

