public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 1;

    int[] sum = new int[n];
    int[][] dp = new int[n][n];

    for (int i = 0; i < n; i++) {
        sum[i] = A[i] + A[(i + 1) % n];
    }

    for (int i = 0; i < n; i++) {
        dp[i][i] = 1;
    }

    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (isPerfectSquare(sum[i] + sum[j])) {
                dp[i][j] = dp[i][j - 1] + dp[i + 1][j];
            }
        }
    }

    return dp[0][n - 1];
}

