public static int squarePermutations(int[] A) {
    int n = A.length;
    Arrays.sort(A);
    boolean[] used = new boolean[n];
    int count = 0;
    for (int i = 0; i < n; i++) {
        if (!used[i]) {
            used[i] = true;
            for (int j = i + 1; j < n; j++) {
                if (!used[j]) {
                    double sum = A[i] + A[j];
                    int root = (int) Math.sqrt(sum);
                    if (root * root == sum) {
                        used[j] = true;
                        count++;
                    }
                }
            }
        }
    }
    return count;
}

