public static int largestRectangleArea(int[] heights) {
    int maxArea = 0;
    for (int i = 0; i < heights.length; i++) {
        int currArea = heights[i];
        for (int j = i + 1; j < heights.length; j++) {
            currArea = Math.max(currArea, heights[j] + currArea);
        }
        maxArea = Math.max(maxArea, currArea);
    }
    return maxArea;
}

public static int largestRectangleArea(int[] heights) {
    int maxArea = 0;
    for (int i = 0; i < heights.length; i++) {
        int minHeight = heights[i];
        for (int j = i; j < heights.length; j++) {
            minHeight = Math.min(minHeight, heights[j]);
            maxArea = Math.max(maxArea, minHeight * (j - i + 1));
        }
    }
    return maxArea;
}

public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int[] prefixSums = new int[n + 1];
    for (int i = 0; i < n; i++) {
        prefixSums[i + 1] = prefixSums[i] + heights[i];
    }
    int maxArea = 0;
    for (int i = 0; i < n; i++) {
        int minHeight = Integer.MAX_VALUE;
        for (int j = i; j >= 0; j--) {
            minHeight = Math.min(minHeight, heights[j]);
            maxArea = Math.max(maxArea, (prefixSums[i + 1] - prefixSums[j]) * minHeight);
        }
    }
    return maxArea;
}

public static int largestRectangleArea(int[] heights) {
    int maxArea = 0;
    for (int i = 0; i < heights.length; i++) {
        int minHeight = heights[i];
        for (int j = i; j < heights.length; j++) {
            if (heights[j] < minHeight) {
                minHeight = heights[j];
            }
            maxArea = Math.max(maxArea, minHeight * (j - i + 1));
        }
    }
    return maxArea;
}

public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int[] left = new int[n];
    int[] right = new int[n];
    int maxArea = 0;
    for (int i = 1; i < n; i++) {
        int curHeight = heights[i];
        int curLeft = 0, curRight = 0;
        for (int j = i - 1; j >= 0; j--) {
            if (heights[j] >= curHeight) {
                curLeft += 1;
            } else {
                break;
            }
        }
        for (int j = i + 1; j < n; j++) {
            if (heights[j] >= curHeight) {
                curRight += 1;
            } else {
                break;
            }
        }
        left[i] = curLeft;
        right[i] = curRight;
        maxArea = Math.max(maxArea, curHeight * (curLeft + curRight + 1));
    }
    return maxArea;
}

