public static int findSmallestInteger(int n) {
    String numberString = Integer.toString(n);
    int[] numberDigits = new int[numberString.length()];
    for (int i = 0; i < numberString.length(); i++) {
        numberDigits[i] = Character.getNumericValue(numberString.charAt(i));
    }
    Arrays.sort(numberDigits);
    String smallestNumber = String.join("", numberDigits);
    return Integer.parseInt(smallestNumber);
}

public static int findSmallestInteger(int n) {
    String number = String.valueOf(n);
    int smallest = -1;
    for (int i = 0; i < number.length(); i++) {
        int digit = number.charAt(i) - '0';
        for (int j = i; j < number.length(); j++) {
            int nextDigit = number.charAt(j) - '0';
            if (digit > nextDigit) {
                smallest = n;
                break;
            } else if (digit == nextDigit) {
                smallest = n;
            } else {
                smallest++;
            }
        }
    }
    return smallest;
}

