public static boolean isBoomerang(int[][] points) {
    if (points.length != 3) return false;
    int[][] p = new int[3][2];
    for (int i = 0; i < 3; i++) {
        p[i][0] = points[i][0];
        p[i][1] = points[i][1];
    }
    Arrays.sort(p, (a, b) -> (a[0] == b[0]) ? a[1] - b[1] : a[0] - b[0]);
    return (p[0][0] * p[1][1] + p[1][0] * p[2][1] + p[2][0] * p[0][1]) == 0;
}

