    int x2 = points[1][0];
    int y2 = points[1][1];
    int x3 = points[2][0];
    int y3 = points[2][1];

    boolean same_X = (x1 == x2) && (x2 == x3);
    boolean same_Y = (y1 == y2) && (y2 == y3);
    boolean different_X = (x1 != x2) && (x2 != x3);
    boolean different_Y = (y1 != y2) && (y2 != y3);

    return (different_X || different_Y) && !(same_X || same_Y);
}

public static boolean isBoomerang(int[][] points) {
    if (points.length != 3) {
        return false;
    }
    int[] point1 = points[0];
    int[] point2 = points[1];
    int[] point3 = points[2];
    int x1 = point1[0], y1 = point1[1];
    int x2 = point2[0], y2 = point2[1];
    int x3 = point3[0], y3 = point3[1];
    double area2 = (x1 * y2 + x2 * y3 + x3 * y1) - (y1 * x2 + y2 * x3 + y3 * x1);
