public static int findNthUglyNumber(int n) {
    int[] uglyNums = new int[n];
    uglyNums[0] = 1;
    int nextUglyIndex = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    int num2 = 2, num3 = 3, num5 = 5;
    while (nextUglyIndex < n) {
        int min = Math.min(Math.min(num2, num3), num5);
        uglyNums[nextUglyIndex] = min;
        if (min == num2) {
            i2++;
            num2 = 2 * uglyNums[i2];
        }
        if (min == num3) {
            i3++;
            num3 = 3 * uglyNums[i3];
        }
        if (min == num5) {
            i5++;
            num5 = 5 * uglyNums[i5];
        }
        nextUglyIndex++;
    }
    return uglyNums[n-1];
}

