public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }

    int energy = 0;
    char currentChar = s.charAt(0);
    int currentLength = 0;

    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == currentChar) {
            currentLength++;
        } else {
            energy = Math.max(energy, currentLength);
            currentChar = s.charAt(i);
            currentLength = 1;
        }
    }

    return Math.max(energy, currentLength);
}

public static int calculateEnergy(String s) {
    int energy = 1;
    char currentChar = s.charAt(0);
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == currentChar) {
            energy++;
        } else {
            currentChar = s.charAt(i);
            energy = 1;
        }
    }
    return energy;
}

