public static int calculateEnergy(String s) {
    int energy = 1;
    char prevChar = s.charAt(0);
    for (int i = 1; i < s.length(); i++) {
        char currentChar = s.charAt(i);
        if (currentChar != prevChar) {
            energy++;
            prevChar = currentChar;
        }
    }
    return energy;
}

public static int calculateEnergy(String s) {
    int maxEnergy = 0, currentEnergy = 0;
    char currentChar = s.charAt(0);
    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == currentChar) {
            currentEnergy++;
        } else {
            currentEnergy = 1;
            currentChar = s.charAt(i);
        }
        maxEnergy = Math.max(maxEnergy, currentEnergy);
    }
    return maxEnergy;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> list = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        list.add(i);
    }
    Collections.sort(list, (a, b) -> {
        StringBuilder str1 = new StringBuilder(a).append(" ");
        StringBuilder str2 = new StringBuilder(b).append(" ");
        if (str1.compareTo(str2) == 0) {
            return a - b;
        } else {
            return str1.compareTo(str2);
        }
    });
    return list;
}

