    }
    result.sort(Comparator.naturalOrder());
    return result;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= 9; i++) {
        result.add(i);
    }
    for (int i = 10; i <= n; i++) {
        int num = i;
        while (num > 0) {
            result.add(num % 10);
            num /= 10;
        }
        Collections.sort(result);
    }
    return result;
}

