public static List<Integer> lexicalOrder(int n) {
        List<Integer> result = new ArrayList<>();
        for (int i = 1; i <= 9; i++) {
            result.add(i);
            if (i * 10 <= n) {
                result.addAll(lexicalOrder(i * 10));
            }
        }
        return result;
    }

