public static int minPerfectSquareSum(int n) {
    int count = 0;
    while (n > 0) {
        int i = 1;
        while (i * i <= n) {
            i++;
        }
        count++;
        n -= i * i;
    }
    return count;
}

public static int minPerfectSquareSum(int n) {
    int count = 0;
    for (int i = 1; i * i <= n; i++) {
        count++;
        n -= i * i;
    }
    return count + (n > 0 ? 1 : 0);
}

