}

public static int minPerfectSquareSum(int n) {
    int minSquaresCount = 0;
    for (int i = 1; i * i <= n; i++) {
        int currSquaresCount = 1;
        int currNum = n - i * i;
        while (currNum > 0) {
            currSquaresCount++;
            currNum = currNum - i * i;
        }
        if (currSquaresCount < minSquaresCount || minSquaresCount == 0) {
            minSquaresCount = currSquaresCount;
        }
    }
    return minSquaresCount;
}

